    powerCabinet: { color: "#fde047", symbol: "CD" },
    cableSpool: { color: "#facc15", symbol: "C" },
    cargoCrate: { color: "#facc15", symbol: "C" },
    palletJack: { color: "#c084fc", symbol: ">>" },
    conferenceSofa: { color: "#34d399", symbol: "HP+" },
    footBath: { color: "#7dd3fc", symbol: "湯" },
