function semanticEffectMotion(type, variant = "", fallback = "energy") {
  const token = `${String(type || "")} ${String(variant || "")}`.toLowerCase();
  if (/gravity|decelerate|accelerate/.test(token)) return "gravity";
  if (/emp|taser|shock|vibe|hack|pair-route|smartphone|gbo|overdrive/.test(token)) return "glitch";
  if (/teleport|warp|substitution|transfer/.test(token)) return "teleport";
  if (/fire|burn|hot|nuclear|rpg|missile/.test(token)) return "combustion";
  if (/railgun|particle|sunbeam|excalibur|slash|shoot|beam/.test(token)) return "beam";
  if (/reload|sustained-fire/.test(token)) return "recoil";
  if (/grit|stand|shield|overheal|beauty/.test(token)) return "shield";
  if (/mana|water|antidote|heal|flora|recovery|cold|ice/.test(token)) return "ripple";
  if (/credits|luck|mystery|transmutation|invention/.test(token)) return "orbit";
  if (/hover|limit-break|speed|acceleration|power/.test(token)) return "flow-up";
  if (/aim|weak|scope|reason|truth/.test(token)) return "shimmer";
  if (/push|impact|storm|violation/.test(token)) return "impact";
  return fallback;
}

function drawGoldTransmutationStages(goldSprite, progress) {
  const reveal = clamp((progress - 0.08) / 0.2, 0, 1);
  const settle = objectEffectEase(clamp((progress - 0.24) / 0.28, 0, 1));
  const fade = 1 - objectEffectEase(clamp((progress - 0.84) / 0.16, 0, 1));
  const smoothReveal = reveal * reveal * (3 - 2 * reveal);
  const ingotWidth = 82;
  const ingotHeight = 29;

  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = smoothReveal * fade;
  drawNormalizedSpriteCentered(
    goldSprite,
    0,
    -42 - (1 - settle) * 30,
    ingotWidth * (0.84 + settle * 0.16),
    ingotHeight * (0.84 + settle * 0.16)
  );
}

// The accepted Electric raster is authored on a diagonal. Stretching its
// square canvas to a horizontal beam and then applying one fixed 45-degree
// correction changes the authored axis whenever the beam aspect ratio changes.
// Like Sunbeam, map the raster's actual source/target anchors directly onto the
// authoritative world-space source/target segment instead.
const QUANTUM_ELECTRIC_TEXTURE_ANCHORS = Object.freeze({
  source: Object.freeze({ x: -0.429, y: 0.36 }),
  target: Object.freeze({ x: 0.408, y: -0.353 })
});

function quantumElectricTextureTransform(effect, thickness) {
  const sourceX = Number(effect?.x) || 0;
  const sourceY = Number(effect?.y) || 0;
  const targetX = Number.isFinite(effect?.targetX) ? Number(effect.targetX) : sourceX;
  const targetY = Number.isFinite(effect?.targetY) ? Number(effect.targetY) : sourceY;
  const dx = targetX - sourceX;
  const dy = targetY - sourceY;
  const length = Math.hypot(dx, dy);
  if (!(length > 0.001)) return null;

  const source = QUANTUM_ELECTRIC_TEXTURE_ANCHORS.source;
  const target = QUANTUM_ELECTRIC_TEXTURE_ANCHORS.target;
  const axisX = target.x - source.x;
  const axisY = target.y - source.y;
  const normalX = -axisY;
  const normalY = axisX;
  const axisMagnitudeSquared = axisX * axisX + axisY * axisY;
  const perpendicularX = -dy / length * thickness;
  const perpendicularY = dx / length * thickness;
  const a = (dx * axisX + perpendicularX * normalX) / axisMagnitudeSquared;
  const c = (dx * axisY + perpendicularX * normalY) / axisMagnitudeSquared;
  const b = (dy * axisX + perpendicularY * normalX) / axisMagnitudeSquared;
  const d = (dy * axisY + perpendicularY * normalY) / axisMagnitudeSquared;
  const e = sourceX - a * source.x - c * source.y;
  const f = sourceY - b * source.x - d * source.y;
  return { a, b, c, d, e, f, sourceX, sourceY, targetX, targetY, length };
}

function drawQuantumElectricDirectedEffect(effect, progress) {
  const definition = GENERATED_EFFECT_TEXTURES["quantum-electric-discharge"];
  if (!definition) return false;
  const [textureKey] = definition;
  const prepared = transparentSpriteSource(state.textures[textureKey], textureKey, 18);
  const sprite = prepared ? normalizedSpriteFrame(prepared, textureKey, 1, 1, 0, 0) : null;
  if (!sprite) return false;
  const reduced = prefersReducedMotion();
  const p = clamp(Number(progress) || 0, 0, 1);
  const pulse = reduced ? 0 : Math.sin(p * Math.PI);
  const transform = quantumElectricTextureTransform(effect, 138 + pulse * 34);
  if (!transform) return false;
  const reveal = reduced ? 1 : objectEffectEase(clamp(p / 0.24, 0, 1));
  const fade = 1 - objectEffectEase(clamp((p - 0.76) / 0.24, 0, 1));
  const dx = transform.targetX - transform.sourceX, dy = transform.targetY - transform.sourceY;
  const nx = -dy / transform.length, ny = dx / transform.length;
  const frontX = transform.sourceX + dx * reveal, frontY = transform.sourceY + dy * reveal;
  const halfWidth = (138 + pulse * 34) * 0.72;
  const inheritedAlpha = ctx.globalAlpha;
  if (fade <= 0.001 || inheritedAlpha <= 0.001) return true;
  ctx.save();
  ctx.globalCompositeOperation = "lighter"; ctx.globalAlpha = inheritedAlpha * fade;
  ctx.beginPath();
  ctx.moveTo(transform.sourceX + nx * halfWidth, transform.sourceY + ny * halfWidth);
  ctx.lineTo(frontX + nx * halfWidth, frontY + ny * halfWidth);
  ctx.lineTo(frontX - nx * halfWidth, frontY - ny * halfWidth);
  ctx.lineTo(transform.sourceX - nx * halfWidth, transform.sourceY - ny * halfWidth); ctx.closePath(); ctx.clip();
  ctx.transform(transform.a, transform.b, transform.c, transform.d, transform.e, transform.f);
  ctx.filter = "brightness(1.14) contrast(1.1) saturate(1.12)";
  applyAteGlowContext(ctx, "beam", (state.frameNow || performance.now()) / 1000, p, 0.98);
  ctx.drawImage(sprite, -0.5, -0.5, 1, 1); ctx.restore();
  if (!reduced && fade > 0.001) {
    ctx.save(); ctx.globalCompositeOperation = "lighter"; ctx.globalAlpha = inheritedAlpha * fade * 0.82;
    ctx.translate(transform.sourceX, transform.sourceY); ctx.rotate(Math.atan2(dy, dx));
    applyAteGlowContext(ctx, "beam", (state.frameNow || performance.now()) / 1000, p + 0.37, 0.72);
    const corona = Math.min(46, Math.max(22, transform.length * 0.06));
    for (const branch of [-1, 1]) {
      const y = branch * (10 + Math.sin(p * 34 + branch * 1.7) * 5);
      ctx.strokeStyle = branch > 0 ? "rgba(103,232,249,.78)" : "rgba(196,181,253,.7)"; ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.moveTo(reveal * transform.length - corona * .5, y * .25); ctx.lineTo(reveal * transform.length - corona * .18, y); ctx.lineTo(reveal * transform.length + corona * .46, y * .72); ctx.stroke();
    }
    ctx.restore();
  }
  return true;
}




function drawPlicyV540PreparationBarrierHit(effect, progress, sprite, defaultSize) {
  const p = clamp(Number(progress) || 0, 0, 1);
  const pulse = Math.sin(p * Math.PI), enter = objectEffectEase(clamp(p / 0.10, 0, 1));
  const fade = 1 - objectEffectEase(clamp((p - 0.64) / 0.36, 0, 1));
  const radiusSize = Number(effect.radius) > 0 ? Number(effect.radius) * 1.9 : defaultSize;
  const size = Math.min(520, Math.max(defaultSize, radiusSize)) * (0.82 + pulse * 0.28 + p * 0.14);
  const targetX = Number.isFinite(effect.targetX) ? effect.targetX : effect.x, targetY = Number.isFinite(effect.targetY) ? effect.targetY : effect.y;
  const directed = ["gunner-missile", "alchemy-excalibur", "action-jump", "fighter-shockwave", "fighter-energy-release"].includes(effect.type) && (targetX !== effect.x || targetY !== effect.y);
  ctx.save(); ctx.globalCompositeOperation = "lighter"; ctx.globalAlpha = enter * fade;
  ctx.translate(directed ? (effect.x + targetX) / 2 : effect.x, directed ? (effect.y + targetY) / 2 : effect.y);
  if (directed) ctx.rotate(Math.atan2(targetY - effect.y, targetX - effect.x) - (effect.type === "alchemy-excalibur" ? Math.PI / 4 : 0));
  drawAnimatedTextureBottom(sprite, 0, size / 2, directed ? Math.max(size, Math.hypot(targetX - effect.x, targetY - effect.y)) : size, size, { mode: directed ? "beam" : semanticEffectMotion(effect.type, effect.variant), progress:p, intensity:0.94, baseAlpha:0.16 });
  ctx.restore(); return true;
}

function drawGunnerHeadshotEffect(effect, progress) {
  if (!["action-gunner-headshot", "action-gunner-aim-headshot"].includes(effect.type)) return false;
  const weaponId = gunnerWeaponIdFromActionVariant(effect.variant);
  const index = GUNNER_WEAPON_CELLS[weaponId];
  if (!Number.isInteger(index)) return false;
  // Cells 0–4 are the authored per-weapon impact strips. They express the
  // target hit; do not reuse the weapons atlas or shift this to the shooter's
  // muzzle. Special ammunition owns its separate action-special-ammo-impact
  // event and deliberately does not enter this renderer.
  const key = `gunner-headshot-impact-${weaponId}`;
  const prepared = transparentSpriteSource(state.textures.gunnerCombatStateEffects?.[index], key, 24);
  const sprite = prepared ? normalizedSpriteFrame(prepared, key, 1, 1, 0, 0) : null;
  if (!sprite) return false;
  const p = clamp(Number(progress) || 0, 0, 1), reduced = prefersReducedMotion();
  const impact = reduced ? 1 : objectEffectEase(clamp(p / .14, 0, 1));
  const tail = 1 - objectEffectEase(clamp((p - .46) / .54, 0, 1));
  const inheritedAlpha = ctx.globalAlpha;
  if (tail <= .001 || inheritedAlpha <= .001) return true;
  const size = 108 + impact * 34;
  ctx.save(); ctx.globalCompositeOperation = "lighter"; ctx.globalAlpha = inheritedAlpha * tail;
  ctx.translate(Number(effect.x) || 0, Number(effect.y) || 0);
  drawAnimatedTextureCentered(sprite, 0, 0, size, size, {
    mode: "impact", progress: reduced ? .5 : p, intensity: .94, baseAlpha: reduced ? .46 : .2, opacityBoost: 2.1
  });
  ctx.restore();
  return true;
}

function drawGeneratedStandaloneEffect(effect, progress) {
  if (effect?.type === "action-gunner-headshot" || effect?.type === "action-gunner-aim-headshot") return drawGunnerHeadshotEffect(effect, progress);
  // The event owns only the ignition kick; sustained jets are state-owned.
  if (effect?.type === "hover-sprint-active") {
    drawHoverSprintActivationJets(effect, progress);
    return true;
  }
  if (drawCommonActionSimpleIcon(effect, progress)) return true;
  if (effect?.type === "fighter-energy-charge") {
    recordVerificationMarkerRender(effect, "ordinary-ec", state.frameNow || performance.now());
  } else if (effect?.type === "action-dodge" && effect?.variant === "fixture-positive-control") {
    recordVerificationMarkerRender(effect, "ordinary-control", state.frameNow || performance.now());
  }
  const definition = effect.type === "limit-break" && effect.variant === "release"
    ? ["limitBreakReleaseEffect", 320]
    : GENERATED_EFFECT_TEXTURES[effect.type];
  if (!definition) return false;
  const [textureKey, defaultSize] = definition;
  const prepared = transparentSpriteSource(state.textures[textureKey], textureKey, 18);
  const sprite = prepared ? normalizedSpriteFrame(prepared, textureKey, 1, 1, 0, 0) : null;
  if (!sprite) return false;
  const preparationBarrierHit = effect.type === "preparation-barrier-hit";
  if (effect.type === "preparation-barrier-hit") {
    return drawPlicyV540PreparationBarrierHit(effect, progress, sprite, defaultSize);
  }
  if (effect.type === "gravity-time-keeper") {
    const arrive = objectEffectEase(clamp(progress / 0.12, 0, 1));
    const fade = 1 - objectEffectEase(clamp((progress - 0.84) / 0.16, 0, 1));
    const size = Math.max(defaultSize, Number(effect.radius || 0) * 2.05);
    ctx.save();
    ctx.translate(effect.x, effect.y);
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = fade * (0.45 + arrive * 0.5);
    drawAnimatedTextureBottom(sprite, 0, size / 2, size, size, {
      mode: "hold",
      progress: 0.5,
      intensity: 0.86,
      baseAlpha: 0.12
    });
    // Complementary E: sparse particles remain spatially fixed for the whole
    // stop. They support the frozen-state read without redrawing the clockwork.
    const fixedMotes = [[-0.36, -0.28], [0.31, -0.34], [-0.42, 0.08], [0.39, 0.16], [-0.2, 0.39], [0.23, 0.33]];
    fixedMotes.forEach(([px, py], index) => {
      ctx.globalAlpha = fade * (0.28 + (index % 3) * 0.11);
      ctx.fillStyle = index % 2 ? "#f9d985" : "#bdf7ff";
      ctx.fillRect(px * size - 2, py * size - 2, 4, 4);
    });
    ctx.restore();
    return true;
  }
  if (effect.type.startsWith("instant-") && effect.type.endsWith("-acquired")) {
    return drawInstantItemAcquisitionEffect(effect, progress, sprite, defaultSize);
  }
  if (effect.type === "transfer-out" || effect.type === "transfer-in") {
    return drawTransferGeneratedEffect(effect, progress, sprite, defaultSize);
  }
  const pulse = Math.sin(Math.min(1, progress) * Math.PI);
  const radiusSize = Number(effect.radius) > 0 ? Number(effect.radius) * 1.9 : defaultSize;
  const size = Math.min(["quantum-nuclear", "quantum-nuclear-fusion"].includes(effect.type) ? 1500 : 520, Math.max(defaultSize, radiusSize)) *
    (0.82 + pulse * 0.28 + progress * 0.14);
  const targetX = Number.isFinite(effect.targetX) ? effect.targetX : effect.x;
  const targetY = Number.isFinite(effect.targetY) ? effect.targetY : effect.y;
  const directed = ["gunner-missile", "alchemy-excalibur", "fighter-shockwave", "fighter-energy-release"].includes(effect.type) && (targetX !== effect.x || targetY !== effect.y);
  const goldTransmutation = effect.type === "quantum-transmutation";
  const renderHeight = goldTransmutation
    ? Math.max(72, size * 0.28)
    : ["fighter-shockwave", "fighter-energy-release"].includes(effect.type)
    ? Math.max(120, Number(effect.radius || 0) * 2.2)
    : size;
  const renderWidth = goldTransmutation ? renderHeight * (510 / 141) : size;
  ctx.save();
  ctx.globalCompositeOperation = preparationBarrierHit ? "source-over" : "lighter";
  ctx.globalAlpha = (1 - progress * 0.28) * (1 - objectEffectEase(clamp((progress - 0.64) / 0.36, 0, 1))) * (preparationBarrierHit ? 0.62 : 1);
  ctx.translate(directed ? (effect.x + targetX) / 2 : effect.x, directed ? (effect.y + targetY) / 2 : effect.y);
  if (directed) {
    const sourceAxisOffset = effect.type === "alchemy-excalibur" ? Math.PI / 4 : 0;
    ctx.rotate(Math.atan2(targetY - effect.y, targetX - effect.x) - sourceAxisOffset);
  }
  drawAnimatedTextureBottom(
    sprite,
    0,
    goldTransmutation ? 30 : renderHeight / 2,
    directed ? Math.max(size, Math.hypot(targetX - effect.x, targetY - effect.y)) : renderWidth,
    renderHeight,
    {
      mode: preparationBarrierHit ? "shield" : directed ? "beam" : semanticEffectMotion(effect.type, effect.variant),
      progress,
      intensity: preparationBarrierHit ? 0.62 : 0.94,
      baseAlpha: preparationBarrierHit ? 0.15 : 0.16,
      opacityBoost: preparationBarrierHit ? 1.2 : 3,
      visibilityProfile: preparationBarrierHit ? "ambient" : "effect"
    }
  );
  if (preparationBarrierHit) {
    const barrierTime = (state.frameNow || performance.now()) / 1000;
    drawPreparationBarrierComplementaryVfx(
      directed ? Math.max(size, Math.hypot(targetX - effect.x, targetY - effect.y)) : renderWidth,
      renderHeight,
      barrierTime,
      (effect.id?.length || 0) * 0.13,
      Math.sin(Math.min(1, progress) * Math.PI)
    );
  }
  if (effect.type === "alchemy-excalibur") {
    const edge = Math.sin(clamp(progress / 0.74, 0, 1) * Math.PI);
    ctx.globalCompositeOperation = "lighter";
    for (let index = 0; index < 14; index += 1) {
      const sweep = clamp((progress - index * 0.018) / 0.58, 0, 1);
      const angle = -0.62 + sweep * 1.24 + (index - 7) * 0.018;
      const radius = size * (0.26 + (index % 5) * 0.035);
      ctx.globalAlpha = edge * (1 - sweep * 0.55) * (0.18 + (index % 4) * 0.06);
      ctx.fillStyle = index % 3 === 0 ? "#ffe6a3" : "#baf6ff";
      ctx.save();
      ctx.rotate(angle);
      ctx.fillRect(radius, -1.2, 18 + (index % 4) * 7, 2.4);
      ctx.restore();
    }
  }
  if (effect.type === "quantum-transmutation") {
    const goldImage = state.textures?.itemTextures?.gold;
    const goldPrepared = goldImage ? transparentSpriteSource(goldImage, "item-gold", 12) : null;
    const goldSprite = goldPrepared ? normalizedSpriteFrame(goldPrepared, "item-gold", 1, 1, 0, 0) : null;
    if (goldSprite) {
      drawGoldTransmutationStages(goldSprite, progress);
    }
  }
  ctx.restore();
  return true;
}

const HOVER_SPRINT_JET_SOURCE_ANCHOR = Object.freeze({
  // Keep the authored pair's semantic bounds, rather than its noisy alpha
  // extrema. The two nozzles are at (527,550)/(727,550) in the 1254 canvas.
  sourceX: 438,
  sourceY: 505,
  sourceWidth: 380,
  sourceHeight: 725,
  nozzleX: 0.5,
  nozzleY: 45 / 725,
  nozzleSpacing: 100 / 380
});

function hoverSprintTravelHeading(player, data) {
  const renderState = state.renderPlayers.get(player?.id);
  const input = player?.id === data?.selfId ? getDirection() : null;
  const dx = Number(input?.dx ?? renderState?.moveX ?? player?.moveX) || 0;
  const dy = Number(input?.dy ?? renderState?.moveY ?? player?.moveY) || 0;
  if (Math.hypot(dx, dy) > 0.01) return Math.atan2(dy, dx);
  const facing = state.facing.get(player?.id) || "down";
  return ({ up: -Math.PI / 2, down: Math.PI / 2, left: Math.PI, right: 0 })[facing] ?? Math.PI / 2;
}

function drawHoverSprintJetPair(anchorX, anchorY, heading, options = {}) {
  const sprite = state.textures?.hoverSprintJetEffect;
  const sourceWidth = Number(sprite?.naturalWidth || sprite?.width) || 0;
  const sourceHeight = Number(sprite?.naturalHeight || sprite?.height) || 0;
  if (!(sourceWidth > 0 && sourceHeight > 0)) return false;
  const {
    height = 72,
    alpha = 1,
    flare = 0,
    pulse = 0,
    reduced = false
  } = options;
  const renderHeight = height * (reduced ? 0.9 : 1 + flare * 0.12);
  const renderWidth = renderHeight * HOVER_SPRINT_JET_SOURCE_ANCHOR.sourceWidth / HOVER_SPRINT_JET_SOURCE_ANCHOR.sourceHeight;
  const nozzleX = renderWidth * HOVER_SPRINT_JET_SOURCE_ANCHOR.nozzleX;
  const nozzleY = renderHeight * HOVER_SPRINT_JET_SOURCE_ANCHOR.nozzleY;
  const inheritedAlpha = ctx.globalAlpha;

  ctx.save();
  ctx.translate(anchorX, anchorY);
  // Source is forward-up / exhaust-down. Rotate exhaust to movement opposite.
  ctx.rotate(heading + Math.PI / 2);
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha *= alpha;
  // One raw paired texture draw: use only its semantic source rectangle, so
  // isolated near-transparent canvas specks cannot shift the nozzle anchor.
  ctx.drawImage(
    sprite,
    HOVER_SPRINT_JET_SOURCE_ANCHOR.sourceX,
    HOVER_SPRINT_JET_SOURCE_ANCHOR.sourceY,
    HOVER_SPRINT_JET_SOURCE_ANCHOR.sourceWidth,
    HOVER_SPRINT_JET_SOURCE_ANCHOR.sourceHeight,
    -nozzleX,
    -nozzleY,
    renderWidth,
    renderHeight
  );

  const nozzleSpacing = renderWidth * HOVER_SPRINT_JET_SOURCE_ANCHOR.nozzleSpacing;
  ctx.fillStyle = "rgba(218,255,255,.88)";
  for (const side of [-1, 1]) {
    const x = side * nozzleSpacing;
    // E: compact nozzle flare, constrained to each emitter.
    ctx.globalAlpha = inheritedAlpha * alpha * (0.22 + flare * 0.44);
    ctx.fillRect(x - 1.8, -2.5, 3.6, 5 + flare * 7);
    if (!reduced && pulse > 0.01) {
      // Two short aft shock arcs, never a circular badge around the actor.
      ctx.globalAlpha = inheritedAlpha * alpha * pulse * 0.22;
      ctx.strokeStyle = "rgba(125,237,255,.72)";
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.ellipse(x, renderHeight * 0.34, 7 + pulse * 9, 3 + pulse * 3, 0, Math.PI * 0.18, Math.PI * 0.82);
      ctx.stroke();
    }
  }
  ctx.restore();
  return true;
}

function drawHoverSprintActivationJets(effect, progress) {
  const player = state.data?.players?.find((entry) => entry?.id === effect.playerId);
  const activeUntil = Number(player?.id === state.data?.selfId ? state.data?.self?.hoverSprintUntil : player?.hoverSprintUntil) || 0;
  // The actor renderer owns all four emitters while HS is active. Event
  // fallback only covers a missing/expired actor and never doubles the jets.
  if (player && activeUntil > estimatedServerNow(state.data)) return true;
  const rendered = player ? renderedPlayer(player) : null;
  const x = Number(rendered?.x ?? effect.x) || 0;
  const y = Number(rendered?.y ?? effect.y) || 0;
  const ignition = objectEffectEase(clamp(progress / 0.15, 0, 1));
  const fade = 1 - objectEffectEase(clamp((progress - 0.7) / 0.3, 0, 1));
  const pulse = Math.sin(clamp(progress / 0.42, 0, 1) * Math.PI);
  const heading = hoverSprintTravelHeading(player || effect, state.data);
  const options = { alpha: fade * ignition, flare: ignition, pulse, reduced: prefersReducedMotion() };
  const feet = drawHoverSprintJetPair(x, y + 23, heading, { ...options, height: 76 + ignition * 10 });
  const back = drawHoverSprintJetPair(x, y - 2, heading, { ...options, height: 66 + ignition * 8 });
  return feet || back;
}

function drawHoverSprintSustainedJets(player, data) {
  const until = Number(player?.id === data?.selfId ? data?.self?.hoverSprintUntil : player?.hoverSprintUntil) || 0;
  if (until <= estimatedServerNow(data)) return false;
  const time = actorVisualTime(player, data) / 1000;
  const reduced = prefersReducedMotion();
  const throttle = reduced ? 0.5 : 0.52 + Math.sin(time * 8.4 + (player.id?.length || 0)) * 0.14;
  // drawHuman() already translates to the current rendered actor position.
  // Two foot nozzles and two upper-back nozzles remain visible together.
  const heading = hoverSprintTravelHeading(player, data);
  const options = { alpha: 0.38 + throttle * 0.24, flare: throttle, pulse: reduced ? 0 : 0.18 + throttle * 0.12, reduced };
  const feet = drawHoverSprintJetPair(0, 23, heading, { ...options, height: 60 });
  const back = drawHoverSprintJetPair(0, -2, heading, { ...options, height: 66 });
  return feet || back;
}

function drawInstantItemAcquisitionEffect(effect, progress, sprite, defaultSize) {
  const fade = 1 - objectEffectEase(clamp((progress - 0.68) / 0.32, 0, 1));
  const targetX = Number(effect.x) || 0;
  const targetY = Number(effect.y) || 0;
  const kind = effect.type.replace(/^instant-/, "").replace(/-acquired$/, "");
  if (!["iai", "stand-firm", "push"].includes(kind)) {
    return drawUtilityInstantItemAcquisitionEffect(effect, progress, sprite, defaultSize, kind);
  }
  ctx.save();
  ctx.translate(targetX, targetY);

  if (kind === "iai") {
    const arrival = objectEffectEase(clamp(progress / 0.18, 0, 1));
    const release = objectEffectEase(clamp((progress - 0.12) / 0.34, 0, 1));
    ctx.rotate(-0.68 + (1 - arrival) * 0.17);
    ctx.translate((1 - arrival) * -84 + release * 12, (1 - arrival) * 35 - release * 6);
    ctx.scale(0.72 + arrival * 0.3 + release * 0.08, 0.6 + arrival * 0.4 - release * 0.08);
    ctx.globalAlpha = fade * (0.22 + arrival * 0.78);
    drawAnimatedTextureCentered(sprite, 0, 0, defaultSize, defaultSize, {
      mode: "beam",
      progress: release,
      intensity: 0.94,
      baseAlpha: 0.12
    });
    ctx.globalCompositeOperation = "lighter";
    for (let index = 0; index < 5; index += 1) {
      const travel = clamp((progress - index * 0.035) / 0.58, 0, 1);
      ctx.globalAlpha = fade * (1 - travel) * (0.28 + index * 0.035);
      ctx.fillStyle = index % 2 ? "#a76dff" : "#8de9ff";
      ctx.beginPath();
      ctx.ellipse(-92 + travel * 154, 52 + index * 7 - travel * 32, 2.2, 0.8, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (kind === "stand-firm") {
    const rise = objectEffectEase(clamp(progress / 0.28, 0, 1));
    const compression = Math.sin(clamp((progress - 0.12) / 0.54, 0, 1) * Math.PI);
    const rebound = objectEffectEase(clamp((progress - 0.46) / 0.34, 0, 1));
    ctx.translate(0, (1 - rise) * 72 - rebound * 10);
    ctx.scale(0.82 + rise * 0.18 + rebound * 0.05, 0.56 + rise * 0.44 - compression * 0.12 + rebound * 0.08);
    ctx.globalAlpha = fade * (0.18 + rise * 0.82);
    drawAnimatedTextureCentered(sprite, 0, 0, defaultSize, defaultSize, {
      mode: "shield",
      progress,
      intensity: 0.9,
      baseAlpha: 0.14
    });
    ctx.globalCompositeOperation = "lighter";
    for (let index = 0; index < 7; index += 1) {
      const lift = clamp((progress - index * 0.04) / 0.7, 0, 1);
      const offsetX = ((index * 37) % 88) - 44;
      ctx.globalAlpha = fade * (1 - lift) * 0.34;
      ctx.fillStyle = index % 3 === 0 ? "#ffd78d" : "#9dfff1";
      ctx.beginPath();
      ctx.arc(offsetX, 78 - lift * (92 + index * 3), 1.2 + (index % 2) * 0.7, 0, Math.PI * 2);
      ctx.fill();
    }
  } else {
    const drive = objectEffectEase(clamp(progress / 0.3, 0, 1));
    const recoil = Math.sin(clamp(progress / 0.48, 0, 1) * Math.PI);
    ctx.translate((1 - drive) * -74 + drive * 18 - recoil * 14, 0);
    ctx.scale(0.64 + drive * 0.42 + recoil * 0.08, 0.84 + drive * 0.16 - recoil * 0.05);
    ctx.globalAlpha = fade * (0.2 + drive * 0.8);
    drawAnimatedTextureCentered(sprite, 0, 0, defaultSize, defaultSize, {
      mode: "impact",
      progress,
      intensity: 0.94,
      baseAlpha: 0.12
    });
    ctx.globalCompositeOperation = "lighter";
    for (let index = 0; index < 6; index += 1) {
      const wake = clamp((progress - index * 0.045) / 0.62, 0, 1);
      ctx.globalAlpha = fade * (1 - wake) * 0.32;
      ctx.fillStyle = index % 2 ? "#ffcb75" : "#ff795d";
      ctx.beginPath();
      ctx.ellipse(-108 + wake * 112, -28 + index * 11, 2.4, 1.1, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.restore();
  return true;
}

function drawUtilityInstantItemAcquisitionEffect(effect, progress, sprite, defaultSize, kind) {
  const fade = 1 - objectEffectEase(clamp((progress - 0.72) / 0.28, 0, 1));
  const enter = objectEffectEase(clamp(progress / 0.3, 0, 1));
  const pulse = Math.sin(clamp(progress / 0.7, 0, 1) * Math.PI);
  const profiles = {
    stamina: { mode: "power", rotate: 1.2, dx: 0, dy: 42, sx: 0.5, sy: 0.5, color: "#ffe08a", mote: "orbit" },
    heal: { mode: "ripple", rotate: -0.12, dx: 0, dy: 58, sx: 0.76, sy: 0.45, color: "#9fffe9", mote: "converge" },
    fire: { mode: "combustion", rotate: 0.08, dx: 0, dy: 76, sx: 0.66, sy: 0.36, color: "#ff963f", mote: "rise" },
    substitution: { mode: "teleport", rotate: 1.55, dx: 34, dy: 0, sx: 0.22, sy: 0.9, color: "#d9a2ff", mote: "cross" },
    warp: { mode: "teleport", rotate: -0.65, dx: -64, dy: 38, sx: 0.42, sy: 0.42, color: "#8dc6ff", mote: "bridge" },
    evade: { mode: "recoil", rotate: 0.06, dx: 72, dy: 0, sx: 0.38, sy: 0.82, color: "#a787ff", mote: "lateral" },
    speed: { mode: "flow-up", rotate: 0, dx: 0, dy: 78, sx: 0.6, sy: 0.34, color: "#76f4ff", mote: "rise" },
    mystery: { mode: "orbit", rotate: 2.4, dx: 0, dy: 0, sx: 0.52, sy: 0.52, color: "#ffcf67", mote: "orbit" },
    mana: { mode: "ripple", rotate: -0.28, dx: -42, dy: 0, sx: 0.48, sy: 0.7, color: "#8ea7ff", mote: "wave" },
    hack: { mode: "glitch", rotate: 0.04, dx: 0, dy: 54, sx: 0.68, sy: 0.5, color: "#77f4ff", mote: "scan" }
  };
  const profile = profiles[kind] || profiles.mana;
  ctx.save();
  ctx.translate(Number(effect.x) || 0, Number(effect.y) || 0);
  const recoil = kind === "evade" ? Math.sin(progress * Math.PI * 2.5) * (1 - progress) * 18 : 0;
  const warpSnap = kind === "warp" ? Math.sin(clamp(progress / 0.54, 0, 1) * Math.PI) * 16 : 0;
  ctx.translate((1 - enter) * profile.dx + recoil + warpSnap, (1 - enter) * profile.dy - pulse * (kind === "fire" || kind === "speed" ? 18 : 6));
  ctx.rotate((1 - enter) * profile.rotate + (kind === "mystery" ? progress * 0.9 : 0));
  ctx.scale(profile.sx + enter * (1 - profile.sx) + pulse * 0.08, profile.sy + enter * (1 - profile.sy) + pulse * 0.06);
  ctx.globalAlpha = fade * (0.18 + enter * 0.82);
  drawAnimatedTextureCentered(sprite, 0, 0, defaultSize, defaultSize, {
    mode: profile.mode,
    progress,
    intensity: 0.92,
    baseAlpha: 0.12
  });
  ctx.restore();

  ctx.save();
  ctx.translate(Number(effect.x) || 0, Number(effect.y) || 0);
  ctx.globalCompositeOperation = "lighter";
  for (let index = 0; index < 7; index += 1) {
    const travel = clamp((progress - index * 0.035) / 0.72, 0, 1);
    let x = ((index * 43) % 96) - 48;
    let y = 58 - travel * 106;
    if (profile.mote === "converge") {
      x *= 1 - travel;
      y = -62 + travel * 62;
    } else if (profile.mote === "cross") {
      x = (index % 2 ? -1 : 1) * (74 - travel * 70);
      y = ((index * 29) % 76) - 38;
    } else if (profile.mote === "bridge") {
      x = -92 + travel * 184;
      y = (index - 3) * 7 + Math.sin(travel * Math.PI) * -22;
    } else if (profile.mote === "lateral") {
      x = (index % 2 ? -1 : 1) * (92 - travel * 34);
      y = (index - 3) * 13;
    } else if (profile.mote === "orbit") {
      const angle = travel * Math.PI * 2 + index * 0.9;
      x = Math.cos(angle) * (58 - travel * 24);
      y = Math.sin(angle) * (38 - travel * 14);
    } else if (profile.mote === "wave") {
      x = -86 + travel * 172;
      y = Math.sin(travel * Math.PI * 3 + index * 0.8) * 26;
    } else if (profile.mote === "scan") {
      x = -76 + travel * 152;
      y = (index - 3) * 10;
    }
    ctx.globalAlpha = fade * (1 - travel) * (0.24 + (index % 3) * 0.055);
    ctx.fillStyle = index % 3 === 0 ? "#ffffff" : profile.color;
    ctx.beginPath();
    ctx.ellipse(x, y, profile.mote === "lateral" ? 3.2 : 1.6, 1.1, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  return true;
}

function drawTransferGeneratedEffect(effect, progress, sprite, defaultSize) {
  const outgoing = effect.type === "transfer-out";
  const targetX = Number.isFinite(effect.targetX) ? effect.targetX : effect.x;
  const targetY = Number.isFinite(effect.targetY) ? effect.targetY : effect.y;
  const eased = outgoing ? 1 - Math.pow(1 - progress, 3) : progress;
  const x = outgoing ? effect.x + (targetX - effect.x) * eased : effect.x;
  const y = outgoing ? effect.y + (targetY - effect.y) * eased : effect.y;
  const pulse = Math.sin(progress * Math.PI);
  const size = defaultSize * (outgoing ? 0.78 + pulse * 0.34 : 1.15 - progress * 0.25 + pulse * 0.18);
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha *= objectEffectEase(clamp(progress / (outgoing ? 0.045 : 0.09), 0, 1)) * (outgoing ? 1 - progress * 0.25 : 1 - progress * 0.4) * (1 - objectEffectEase(clamp((progress - 0.72) / 0.28, 0, 1)));
  ctx.translate(x, y);
  if (outgoing && (targetX !== effect.x || targetY !== effect.y)) {
    ctx.rotate(Math.atan2(targetY - effect.y, targetX - effect.x));
  }
  drawAnimatedTextureCentered(sprite, 0, 0, size, size, {
    mode: "teleport",
    progress,
    intensity: 0.92,
    baseAlpha: 0.14
  });
  ctx.restore();
  return true;
}

const TACTICAL_SYSTEM_EFFECT_CELLS = {
  "action-smartphone": 1,
  "action-smartphone-repair": 1,
  "pair-route-violation": 2,
  "action-taser": 4,
  "gravity-accelerate": 5,
  "gravity-decelerate": 5,
  "gravity-storm": 6,
  "alchemy-object-recharge": 7,
  "alchemy-human-transmutation": 8,
  "alchemy-excalibur": 8,
  "alchemy-particle-cannon": 8
};

function drawTacticalSystemsEffect(effect, progress) {
  // Shared smartphone actions use the same single-icon presentation as the shop.
  // Operator-only tactical effects continue through their dedicated renderer.
  if (drawCommonActionSimpleIcon(effect, progress)) return true;
  const index = TACTICAL_SYSTEM_EFFECT_CELLS[effect.type];
  if (!Number.isInteger(index)) return false;
  const atlas = transparentSpriteSource(state.textures.tacticalSystemsAtlas, "tactical-systems-atlas", 18);
  const sprite = atlas ? normalizedSpriteFrame(atlas, `tactical-system-${index}`, 3, 3, Math.floor(index / 3), index % 3) : null;
  if (!sprite) return false;
  const pulse = Math.sin(Math.min(1, progress) * Math.PI);
  const base = Math.max(105, Number(effect.radius) || 120);
  const size = Math.min(index === 6 ? 560 : 390, base * (1.55 + progress * 0.65 + pulse * 0.2));
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha *= objectEffectEase(clamp(progress / 0.075, 0, 1)) * (1 - progress * 0.3) * (1 - objectEffectEase(clamp((progress - 0.62) / 0.38, 0, 1)));
  ctx.translate(effect.x, effect.y);
  ctx.rotate(index === 5 ? progress * 0.24 : 0);
  drawAnimatedTextureBottom(sprite, 0, size / 2, size, size, {
    mode: semanticEffectMotion(effect.type, effect.variant, index === 6 ? "gravity" : "shimmer"),
    progress,
    intensity: 0.9,
    baseAlpha: 0.15
  });
  ctx.restore();
  return true;
}

function drawFloraGeneratedEffect(effect, progress, sunbeam) {
  const source = sunbeam ? state.textures.floraSunbeamV3 : state.textures.floraHealV1;
  const key = sunbeam ? "flora-sunbeam-v3" : "flora-heal-v1";
  const prepared = transparentSpriteSource(source, key, 18);
  const sprite = prepared ? normalizedSpriteFrame(prepared, key, 1, 1, 0, 0) : null;
  if (!sprite) return false;
  const reduced = prefersReducedMotion();
  const safeProgress = clamp(Number(progress) || 0, 0, 1);
  const pulse = reduced ? 0 : Math.sin(safeProgress * Math.PI);
  const fade = 1 - objectEffectEase(clamp((safeProgress - 0.76) / 0.24, 0, 1));
  if (fade <= 0.001) return true;
  const inheritedAlpha = ctx.globalAlpha;
  if (inheritedAlpha <= 0.001) return true;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = inheritedAlpha * fade;
  if (sunbeam) {
    const sourceX = Number(effect.x) || 0;
    const sourceY = Number(effect.y) || 0;
    const targetX = Number.isFinite(Number(effect.targetX)) ? Number(effect.targetX) : sourceX;
    const targetY = Number.isFinite(Number(effect.targetY)) ? Number(effect.targetY) : sourceY;
    const dx = targetX - sourceX;
    const dy = targetY - sourceY;
    const length = Math.hypot(dx, dy);
    // A coincident target has no beam axis. Show the existing texture as a
    // compact source result instead of inventing a 900-unit ray to the right.
    if (length <= 0.001) {
      const size = 164 + pulse * 16;
      drawAnimatedTextureCentered(sprite, sourceX, sourceY, size, size * 0.58, {
        mode: "beam", progress: reduced ? 0.5 : safeProgress, intensity: 0.8, baseAlpha: 0.2
      });
    } else {
      const sourceAnchor = 0.16;
      const targetAnchor = 0.87;
      const renderWidth = length / (targetAnchor - sourceAnchor);
      const renderCenterX = (0.5 - sourceAnchor) * renderWidth;
      ctx.translate(sourceX, sourceY);
      ctx.rotate(Math.atan2(dy, dx));
      // This is an anchor registration, not a max-size request. The current
      // animated helper aspect-fits its source, which can shorten a long beam
      // and miss targetAnchor. Stretch only this authored directional raster
      // across its declared source/target channel.
      const desiredHeight = 390 + pulse * 55;
      const naturalShortHeight = Math.max(.5, renderWidth * sprite.height / sprite.width);
      const renderHeight = Math.min(desiredHeight, naturalShortHeight);
      ctx.drawImage(sprite, renderCenterX - renderWidth / 2, -renderHeight / 2, renderWidth, renderHeight);
    }
  } else {
    const size = Math.max(190, Number(effect.radius || 110) * 1.9) * (0.9 + pulse * 0.12);
    drawAnimatedTextureCentered(sprite, Number(effect.x) || 0, (Number(effect.y) || 0) - size * 0.03, size, size, {
      mode: "flow-up", progress: reduced ? 0.5 : safeProgress, intensity: 0.96, baseAlpha: 0.22
    });
  }
  ctx.restore();
  return true;
}

function drawDirectedEnergyEffect(effect, progress, now) {
  const sourceX = Number(effect.x) || 0;
  const sourceY = Number(effect.y) || 0;
  const targetX = Number.isFinite(Number(effect.targetX)) ? Number(effect.targetX) : sourceX;
  const targetY = Number.isFinite(Number(effect.targetY)) ? Number(effect.targetY) : sourceY;
  const flora = effect.type === "flora-sunbeam";
  const particle = String(effect.type || "").includes("particle");
  const reduced = prefersReducedMotion();
  const p = clamp(Number(progress) || 0, 0, 1);
  const fade = 1 - objectEffectEase(clamp((p - 0.76) / 0.24, 0, 1));
  const distance = Math.hypot(targetX - sourceX, targetY - sourceY);
  const width = flora ? 34 : particle ? 42 : 18;
  const inheritedAlpha = ctx.globalAlpha;
  if (fade <= 0.001 || inheritedAlpha <= 0.001) return;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = inheritedAlpha * fade;
  if (distance <= 0.001) {
    const radius = width * (reduced ? 1.25 : 1.05 + Math.sin(p * Math.PI) * 0.38);
    const bloom = ctx.createRadialGradient(sourceX, sourceY, 0, sourceX, sourceY, radius * 2.2);
    bloom.addColorStop(0, flora ? "rgba(254,240,138,.95)" : particle ? "rgba(103,232,249,.92)" : "rgba(248,250,252,.9)");
    bloom.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = bloom;
    ctx.beginPath(); ctx.arc(sourceX, sourceY, radius * 2.2, 0, Math.PI * 2); ctx.fill();
  } else {
    const gradient = ctx.createLinearGradient(sourceX, sourceY, targetX, targetY);
    gradient.addColorStop(0, flora ? "#fef08a" : particle ? "#67e8f9" : "#f8fafc");
    gradient.addColorStop(0.55, flora ? "#facc15" : particle ? "#38bdf8" : "#c4b5fd");
    gradient.addColorStop(1, "rgba(255,255,255,0.05)");
    ctx.strokeStyle = gradient;
    ctx.lineWidth = width * (reduced ? 0.72 : 0.65 + Math.sin(Number(now || 0) / 70) * 0.08);
    ctx.beginPath(); ctx.moveTo(sourceX, sourceY); ctx.lineTo(targetX, targetY); ctx.stroke();
    ctx.strokeStyle = "rgba(255,255,255,0.9)";
    ctx.lineWidth = Math.max(2, width * 0.2); ctx.stroke();
  }
  ctx.restore();
}

const ACTION_EFFECT_CELLS = {
  "action-task": 0,
  "action-grit": 1,
  "action-stand": 1,
  "action-dodge": 2,
  "action-rest": 3,
  "action-teleport": 4,
  "action-heart-teleport": 4,
  "action-warp": 5,
  "action-ninjutsu-focus": 6,
  "gunner-passive-aim": 6,
  "action-shoot": 7,
  "action-reason": 7,
  "action-push": 7,
  "action-sabotage": 7,
  "action-repair": 8,
  "action-vent": 9,
  "action-vending": 10,
  "action-renki": 11,
  "action-mana": 11,
  "action-alchemy": 11,
  "action-rational-free": 11,
  "fighter-slash": 7,
  "fighter-slash-parry": 7,
  "fighter-iaido": 7
};

const GUNNER_WEAPON_CELLS = { handgun: 0, smg: 1, assault: 2, sniper: 3, taser: 4 };

function gunnerWeaponIdFromActionVariant(variant, fallback = "") {
  const weaponId = String(variant || "")
    .split(":")
    .find((token) => GUNNER_WEAPON_MOTION_IDS.includes(token));
  if (weaponId) return weaponId;
  return GUNNER_WEAPON_MOTION_IDS.includes(fallback) ? fallback : "";
}

function drawGunnerActionEffect(effect, progress) {
  if (effect.type !== "action-shoot") return false;
  const weaponId = gunnerWeaponIdFromActionVariant(effect.variant);
  if (!weaponId) return false;
  const sourceIndex = 5 + GUNNER_WEAPON_CELLS[weaponId];
  const prepared = transparentSpriteSource(state.textures.gunnerCombatStateEffects?.[sourceIndex], `gunner-combat-state-${sourceIndex}`, 24);
  const sprite = prepared ? normalizedSpriteFrame(prepared, `gunner-combat-state-${sourceIndex}`, 1, 1, 0, 0) : null;
  if (!sprite) return false;
  const reduced = prefersReducedMotion(), p = clamp(Number(progress) || 0, 0, 1);
  const pulse = reduced ? 0 : Math.sin(p * Math.PI);
  const fade = 1 - objectEffectEase(clamp((p - .72) / .28, 0, 1));
  const dx = Number(effect.targetX) - Number(effect.x), dy = Number(effect.targetY) - Number(effect.y);
  const hasTargetAxis = Number.isFinite(dx) && Number.isFinite(dy) && Math.hypot(dx, dy) > .001;
  const direction = hasTargetAxis ? cardinalDirectionVector(dx, dy) : { dx: 1, dy: 0 };
  const muzzle = ({ handgun:{forward:29,height:-32}, smg:{forward:37,height:-34}, assault:{forward:43,height:-36}, sniper:{forward:57,height:-37}, taser:{forward:31,height:-32} })[weaponId] || {forward:35,height:-34};
  const length = ({handgun:42,smg:48,assault:56,sniper:72,taser:40})[weaponId] || 46;
  const height = ({handgun:34,smg:38,assault:42,sniper:48,taser:34})[weaponId] || 38;
  const horizontal = direction.dx !== 0;
  const startX = Number(effect.x) + (horizontal ? 0 : direction.dy < 0 ? 8 : -8) + direction.dx * muzzle.forward;
  const startY = Number(effect.y) + (horizontal ? muzzle.height : direction.dy < 0 ? -43 : -10) + direction.dy * muzzle.forward;
  const inheritedAlpha = ctx.globalAlpha;
  if (fade <= 0.001 || inheritedAlpha <= 0.001) return true;
  ctx.save(); ctx.globalCompositeOperation = "lighter"; ctx.globalAlpha = inheritedAlpha * fade;
  ctx.translate(startX, startY); ctx.rotate(Math.atan2(direction.dy, direction.dx));
  // Cropping the full-canvas authored flash restores its intended muzzle-scale
  // read; this modest display scale remains local to the weapon hand.
  drawAnimatedTextureCentered(sprite, length / 2, 0, length * 1.28, (height + pulse * 8) * 1.28, {mode:"beam", progress: reduced ? .5 : p, intensity:.95, baseAlpha:.18});
  ctx.restore(); return true;
}

